INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 1, 'Quantitative Aptitude', 'Circle Geometry (Diagram)', 'Medium', 'In the given figure, O is the center of a circle of radius R = 13 cm, and chord AB = 24 cm. A perpendicular OM is drawn from O to chord AB and extended to meet the minor arc AB at point P. What are the lengths of segment MP and chord AP?', 1, '<svg viewBox="0 0 440 240" xmlns="http://www.w3.org/2000/svg">
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'MP = 8 cm, AP = 4\\sqrt{13} cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'MP = 5 cm, AP = 12\\sqrt{2} cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'MP = 8 cm, AP = 6\\sqrt{5} cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'MP = 7 cm, AP = 4\\sqrt{13} cm');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 2, 'Quantitative Aptitude', 'Data Interpretation (Bar Chart)', 'Medium', 'Refer to the bar chart showing Revenue and Expenditure (in ₹ Crores) from 2023 to 2026. Given that Profit % = \\frac{\\text{Revenue} - \\text{Expenditure}}{\\text{Expenditure}} \\times 100, in which year did the company record the highest Profit Percentage, and what was its value?', 1, '<svg viewBox="0 0 460 240" xmlns="http://www.w3.org/2000/svg">
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '2024 (33.33%)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '2025 (50.00%)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '2026 (33.33%)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '2023 (25.00%)');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 3, 'Quantitative Aptitude', 'Definite Integration & Calculus', 'Hard', 'Evaluate the definite integral: I = \\int_{0}^{\\pi/2} \\frac{\\sqrt{\\sin \\theta}}{\\sqrt{\\sin \\theta} + \\sqrt{\\cos \\theta}} d\\theta', 0, NULL, 'Using the King property \\int_{0}^{a} f(\\theta) d\\theta = \\int_{0}^{a} f(a - \\theta) d\\theta with a = \\frac{\\pi}{2}, we get I = \\int_{0}^{\\pi/2} \\frac{\\sqrt{\\cos \\theta}}{\\sqrt{\\cos \\theta} + \\sqrt{\\sin \\theta}} d\\theta. Adding both equations gives 2I = \\int_{0}^{\\pi/2} 1 d\\theta = \\frac{\\pi}{2} \\Rightarrow I = \\frac{\\pi}{4}.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '\\frac{\\pi}{2}');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '\\frac{\\pi}{4}');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '\\frac{\\pi}{3}');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '\\pi');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 4, 'Quantitative Aptitude', 'Eigenvalues & Linear Algebra', 'Hard', 'If \\lambda_1, \\lambda_2, \\lambda_3 are the eigenvalues of the matrix A = [[2, 1, 0], [0, 3, 4], [0, 0, 5]], then what is the value of \\sum_{i=1}^{3} \\lambda_i^2 + \\det(A)?', 0, NULL, 'Since A is an upper triangular matrix, its eigenvalues are the diagonal entries: \\lambda_1 = 2, \\lambda_2 = 3, \\lambda_3 = 5. Thus \\sum_{i=1}^{3} \\lambda_i^2 = 2^2 + 3^2 + 5^2 = 4 + 9 + 25 = 38. Also, \\det(A) = \\lambda_1 \\times \\lambda_2 \\times \\lambda_3 = 2 \\times 3 \\times 5 = 30. Total = 38 + 30 = 68.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '68');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '38');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '58');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '40');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 5, 'Quantitative Aptitude', 'Algebra & Surds', 'Medium', 'If x + \\frac{1}{x} = 4, then what is the exact value of x^3 + \\frac{1}{x^3}?', 0, NULL, 'Using the algebraic identity: if x + \\frac{1}{x} = k, then x^3 + \\frac{1}{x^3} = k^3 - 3k. Substituting k = 4 gives 4^3 - 3(4) = 64 - 12 = 52.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '64');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '52');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '48');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '56');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 6, 'Quantitative Aptitude', 'Profit, Loss & Discount', 'Medium', 'A shopkeeper marks his goods 40% above the cost price and allows a discount of 25% on the marked price. What is his net profit or loss percentage?', 0, NULL, 'Let Cost Price (CP) = 100. Marked Price (MP) = 100 + 40% of 100 = 140. Selling Price (SP) after 25% discount = 140 × (1 - 0.25) = 140 × 0.75 = 105. Net Profit = 105 - 100 = 5, which is 5% Profit.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '5% Profit');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '15% Profit');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '5% Loss');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '10% Profit');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 7, 'Quantitative Aptitude', 'Percentages', 'Easy', 'If the price of sugar increases by 25%, by what percentage must a household reduce its consumption so that the total expenditure on sugar remains unchanged?', 0, NULL, 'Formula for reduction % = [R / (100 + R)] × 100. Substituting R = 25: [25 / 125] × 100 = (1/5) × 100 = 20%.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '25%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '20%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '16.67%');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '15%');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 8, 'Quantitative Aptitude', 'Compound Interest', 'Hard', 'The difference between Compound Interest and Simple Interest on a certain sum at 10% per annum for 3 years is ₹930. Find the principal sum.', 0, NULL, 'For 3 years, CI - SI = P × (R/100)² × (300 + R)/100. Here, 930 = P × (10/100)² × (310/100) = P × (1/100) × (31/10) = 31P / 1000. Thus, P = (930 × 1000) / 31 = ₹30,000.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '₹25,000');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '₹30,000');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '₹31,000');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '₹28,500');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 9, 'Quantitative Aptitude', 'Algebra', 'Medium', 'If x + (1/x) = 4, then what is the value of x³ + (1/x³)?', 0, NULL, 'Using the algebraic identity: if x + 1/x = k, then x³ + 1/x³ = k³ - 3k. Substituting k = 4: 4³ - 3(4) = 64 - 12 = 52.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '64');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '52');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '48');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '56');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 10, 'Quantitative Aptitude', 'Time, Speed & Distance', 'Medium', 'A train 240 meters long passes a pole in 24 seconds. How long will it take to pass a platform 650 meters long?', 0, NULL, 'Speed of the train = 240m / 24s = 10 m/s. To pass a 650m platform, total distance = 240 + 650 = 890 meters. Time taken = 890 / 10 = 89 seconds.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '65 seconds');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '89 seconds');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '100 seconds');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '75 seconds');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 11, 'Quantitative Aptitude', 'Ratio & Proportion', 'Easy', 'If A : B = 3 : 4 and B : C = 8 : 9, then what is the ratio A : B : C?', 0, NULL, 'Multiply the first ratio A : B by 2 to make B equal to 8: A : B = 6 : 8. Since B : C = 8 : 9, combining them gives A : B : C = 6 : 8 : 9.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '3 : 4 : 9');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '6 : 8 : 9');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '8 : 12 : 15');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '6 : 9 : 12');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 12, 'Quantitative Aptitude', 'Geometry', 'Hard', 'In a circle of radius 13 cm, two parallel chords of lengths 24 cm and 10 cm are drawn on the same side of the center. What is the distance between the two chords?', 0, NULL, 'Half-lengths of chords are 12 cm and 5 cm. Distance of 24 cm chord from center = √(13² - 12²) = 5 cm. Distance of 10 cm chord from center = √(13² - 5²) = 12 cm. Since they are on the same side, distance between them = 12 - 5 = 7 cm.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '7 cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '17 cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '5 cm');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '12 cm');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 13, 'Quantitative Aptitude', 'Number System', 'Medium', 'What is the remainder when 2³¹ is divided by 5?', 0, NULL, 'We can write 2³¹ = 2 × (2²)¹⁵ = 2 × 4¹⁵. Since 4 ≡ -1 (mod 5), we have 2 × (-1)¹⁵ = -2 ≡ 3 (mod 5). Thus the remainder is 3.', 'C');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '2');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '3');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '4');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 14, 'Quantitative Aptitude', 'Averages', 'Easy', 'The average weight of 20 students in a class is 45 kg. When the weight of the teacher is included, the average weight increases by 1.5 kg. What is the weight of the teacher?', 0, NULL, 'New average of 21 people = 45 + 1.5 = 46.5 kg. Teacher weight = Old Average + (Total people × increase) = 45 + (21 × 1.5) = 45 + 31.5 = 76.5 kg.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '75.5 kg');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '76.5 kg');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '72 kg');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '78.5 kg');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 15, 'Quantitative Aptitude', 'Trigonometry', 'Medium', 'If \\sin \\theta + \\cos \\theta = \\sqrt{2} \\cos \\theta for 0 < \\theta < \\frac{\\pi}{2}, then what is the value of \\tan \\theta?', 0, NULL, 'Dividing both sides by \\cos \\theta gives \\frac{\\sin \\theta}{\\cos \\theta} + 1 = \\sqrt{2} \\Rightarrow \\tan \\theta + 1 = \\sqrt{2} \\Rightarrow \\tan \\theta = \\sqrt{2} - 1.', 'A');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '\\sqrt{2} - 1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '\\sqrt{2} + 1');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '\\frac{1}{\\sqrt{2}}');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '2 - \\sqrt{2}');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 16, 'Quantitative Aptitude', 'Mensuration', 'Medium', 'If the radius r of the base of a right circular cylinder (V = \\pi r^2 h) is halved and its height h is doubled, then the new volume V_{new} becomes:', 0, NULL, 'Original volume V = \\pi r^2 h. New volume V_{new} = \\pi (\\frac{r}{2})^2 (2h) = \\pi (\\frac{r^2}{4})(2h) = \\frac{1}{2} \\pi r^2 h = \\frac{V}{2}.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'V (Unchanged)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '\\frac{V}{2} (Halved)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '2V (Doubled)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '\\frac{V}{4} (One-fourth)');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 17, 'Quantitative Aptitude', 'Mixtures & Alligation', 'Hard', 'A vessel contains 60 liters of pure milk. 12 liters of milk are drawn out and replaced with water, and this process is repeated a second time. What quantity of milk is left finally?', 0, NULL, 'Using the replacement formula: Final Milk = C \\times (1 - \\frac{x}{C})^n = 60 \\times (1 - \\frac{12}{60})^2 = 60 \\times (\\frac{4}{5})^2 = 60 \\times \\frac{16}{25} = 38.4 liters.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '36 liters');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '38.4 liters');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '40.2 liters');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '42 liters');
