INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 19, 'Quantitative Aptitude', 'Mensuration', 'Medium', 'If the radius of the base of a right circular cylinder is halved and its height is doubled, then the volume of the new cylinder compared to the original volume becomes:', 0, NULL, 'Original volume V = πr²h. New volume V_new = π(r/2)²(2h) = π(r²/4)(2h) = (1/2)πr²h = V/2. Hence, the volume is halved.', 'B');
