INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 20, 'Quantitative Aptitude', 'Mixtures & Alligation', 'Hard', 'A vessel contains 60 liters of milk. 12 liters of milk are taken out and replaced with water. Then again 12 liters of the mixture are taken out and replaced with water. What is the final quantity of milk left in the vessel?', 0, NULL, 'Final Milk = Initial × (1 - x/C)^n = 60 × (1 - 12/60)² = 60 × (4/5)² = 60 × (16/25) = 38.4 liters.', 'B');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '36 liters');
