INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@demo_exam, 21, 'Logical Reasoning', 'Number Series', 'Easy', 'Find the missing number in the series: 7, 15, 31, 63, 127, ?', 0, NULL, 'The pattern follows (×2 + 1): 7×2+1 = 15, 15×2+1 = 31, 31×2+1 = 63, 63×2+1 = 127, 127×2+1 = 255.', 'C');
